-- Read-only metadata export. Run the entire query in the remote SQL Editor.
-- Export the result as JSON. No player rows, emails, JWTs or credentials are read.
with app_tables as (
 select c.oid,n.nspname as schema,c.relname as name,c.relrowsecurity as rls,c.relforcerowsecurity as force_rls
 from pg_class c join pg_namespace n on n.oid=c.relnamespace
 where n.nspname in ('public','app_private') and c.relkind in ('r','p')
), snapshot as (
select jsonb_build_object(
 'formatVersion',1,
 'views',coalesce((select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'options',c.reloptions,'definition',pg_get_viewdef(c.oid,true),'materialized',c.relkind='m') order by n.nspname,c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','app_private') and c.relkind in ('v','m')),'[]'::jsonb),
 'sequences',coalesce((select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'type',format_type(s.seqtypid,null),'start',s.seqstart,'increment',s.seqincrement,'min',s.seqmin,'max',s.seqmax,'cache',s.seqcache,'cycle',s.seqcycle) order by n.nspname,c.relname) from pg_sequence s join pg_class c on c.oid=s.seqrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','app_private')),'[]'::jsonb),
 'tables',coalesce((select jsonb_agg(to_jsonb(t)-'oid' order by schema,name) from app_tables t),'[]'::jsonb),
 'columns',coalesce((select jsonb_agg(jsonb_build_object('schema',t.schema,'table',t.name,'name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'nullable',not a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid),'generated',a.attgenerated,'identity',a.attidentity) order by t.schema,t.name,a.attnum)
 from app_tables t join pg_attribute a on a.attrelid=t.oid and a.attnum>0 and not a.attisdropped left join pg_attrdef d on d.adrelid=t.oid and d.adnum=a.attnum),'[]'::jsonb),
 'constraints',coalesce((select jsonb_agg(jsonb_build_object('schema',t.schema,'table',t.name,'name',c.conname,'definition',pg_get_constraintdef(c.oid)) order by t.schema,t.name,c.conname) from app_tables t join pg_constraint c on c.conrelid=t.oid),'[]'::jsonb),
 'indexes',coalesce((select jsonb_agg(jsonb_build_object('schema',schemaname,'table',tablename,'name',indexname,'definition',indexdef) order by schemaname,tablename,indexname) from pg_indexes where schemaname in ('public','app_private')),'[]'::jsonb),
 'functions',coalesce((select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'arguments',pg_get_function_identity_arguments(p.oid),'definition',pg_get_functiondef(p.oid),'securityDefiner',p.prosecdef,'config',p.proconfig) order by n.nspname,p.proname,pg_get_function_identity_arguments(p.oid)) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','app_private') and p.prokind='f' and not exists(select 1 from pg_depend dep where dep.classid='pg_proc'::regclass and dep.objid=p.oid and dep.deptype='e')),'[]'::jsonb),
 'policies',coalesce((select jsonb_agg(to_jsonb(p) order by schemaname,tablename,policyname) from pg_policies p where schemaname in ('public','app_private') or (schemaname='storage' and (policyname like 'avatars_%' or policyname like 'notice_images_%' or policyname like 'showcase_images_%'))),'[]'::jsonb),
 'triggers',coalesce((select jsonb_agg(jsonb_build_object('schema',t.schema,'table',t.name,'name',g.tgname,'enabled',g.tgenabled,'definition',pg_get_triggerdef(g.oid)) order by t.schema,t.name,g.tgname) from app_tables t join pg_trigger g on g.tgrelid=t.oid where not g.tgisinternal),'[]'::jsonb),
 'enums',coalesce((select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',t.typname,'value',e.enumlabel) order by n.nspname,t.typname,e.enumsortorder) from pg_type t join pg_namespace n on n.oid=t.typnamespace join pg_enum e on e.enumtypid=t.oid where n.nspname in ('public','app_private')),'[]'::jsonb),
 'tableGrants',coalesce((select jsonb_agg(jsonb_build_object('schema',table_schema,'table',table_name,'role',grantee,'privilege',privilege_type,'grantable',is_grantable) order by table_schema,table_name,grantee,privilege_type) from information_schema.table_privileges where table_schema in ('public','app_private') and grantee in ('PUBLIC','anon','authenticated','service_role')),'[]'::jsonb),
 'columnGrants',coalesce((select jsonb_agg(jsonb_build_object('schema',table_schema,'table',table_name,'column',column_name,'role',grantee,'privilege',privilege_type) order by table_schema,table_name,column_name,grantee,privilege_type) from information_schema.column_privileges where table_schema in ('public','app_private') and grantee in ('PUBLIC','anon','authenticated','service_role')),'[]'::jsonb),
 'functionGrants',coalesce((select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'arguments',pg_get_function_identity_arguments(p.oid),'role',r.role,'execute',has_function_privilege(r.role,p.oid,'EXECUTE')) order by n.nspname,p.proname,pg_get_function_identity_arguments(p.oid),r.role) from pg_proc p join pg_namespace n on n.oid=p.pronamespace cross join (values('anon'),('authenticated'),('service_role')) r(role) where n.nspname in ('public','app_private') and p.prokind='f' and not exists(select 1 from pg_depend dep where dep.classid='pg_proc'::regclass and dep.objid=p.oid and dep.deptype='e')),'[]'::jsonb),
 'schemaGrants',coalesce((select jsonb_agg(jsonb_build_object('schema',n.nspname,'role',r.role,'usage',has_schema_privilege(r.role,n.oid,'USAGE'),'create',has_schema_privilege(r.role,n.oid,'CREATE')) order by n.nspname,r.role) from pg_namespace n cross join (values('anon'),('authenticated'),('service_role')) r(role) where n.nspname in ('public','app_private')),'[]'::jsonb),
 'publication',coalesce((select jsonb_agg(jsonb_build_object('publication',pubname,'schema',schemaname,'table',tablename) order by pubname,schemaname,tablename) from pg_publication_tables where pubname='supabase_realtime'),'[]'::jsonb),
 'buckets',coalesce((select jsonb_agg(jsonb_build_object('id',id,'public',public,'file_size_limit',file_size_limit,'allowed_mime_types',allowed_mime_types) order by id) from storage.buckets where id in ('avatars','aquarium-backgrounds','regions','collectibles','notice-images','catch-showcases')),'[]'::jsonb)
) as structure)
select jsonb_build_object('capturedAt',to_char(clock_timestamp() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'),'database',current_database(),'serverVersion',current_setting('server_version'),'structure',structure) as snapshot from snapshot;
